"""
Утренняя сводка и разговор без кнопки.

  • Каждое утро (по умолчанию в 7:30) — уведомление: погода, события календаря, напоминания на сегодня,
    карточки к повторению, открытые дела. Время и выключатель — в настройках телефона, там же «Прислать сейчас».
  • «Что у меня сегодня?» голосом — та же сводка.
  • Разговор без кнопки (настройки → «Разговор без кнопки»): нажал на сферу один раз — и говоришь подряд,
    Atlas сам слушает после каждого ответа. Скажи «всё», «спасибо», «хватит» или просто помолчи — разговор
    закончится. Нажатие на сферу, пока Atlas говорит, — замолчать и закончить.

    python apply_brief.py
    python apply_brief.py --rollback
"""
import base64
import hashlib
import os
import re
import shutil
import subprocess
import sys
import time

for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

ROOT = os.path.dirname(os.path.abspath(__file__))
ORIG = {'cloud/atlas_cloud.py': 'b3cbe8d4ac4b8a95a98a5f8d527c6e713f2ad6a658619f4ad61abdaff87e76e4', 'phone/panels.py': '469736b9365252b5dbe478260cff6da5969b30d3f90d27f97331e1a625b193b3', 'phone/static/index.html': '85322b1f3bb4b3ebcec89adbea0c82847e77fb6561ea1afa436945cfd8cbf6d4', 'phone/static/sw.js': '78c3d78fd65eab337b027ae402567984dfbbfc89245c15acc0e6ac1c9e2a61e2', 'tests/test_cloud_brain.py': '951db11773be186ff4f9c502d33ed03621187ac9b1224754c11999d107722b44', 'tests/test_reminders.py': '077a2e7551cdb63cdd2e74041f75c978a12c2b8e7e21d1ad2f201eaf2596d6ce', 'core/briefing.py': None}
NEW = {'cloud/atlas_cloud.py': '', 'phone/panels.py': '', 'phone/static/index.html': '', 'phone/static/sw.js': '', 'tests/test_cloud_brain.py': '', 'tests/test_reminders.py': '', 'core/briefing.py': ''}
TAG = "backup_brief_"


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel, h in ORIG.items():
        if h is None:
            if os.path.exists(p(rel)):
                os.remove(p(rel))
        else:
            shutil.copy2(os.path.join(backup, *rel.split("/")), p(rel))
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith(TAG))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if os.path.exists(p('core/briefing.py')) and 'def build' in open(p('core/briefing.py'), encoding="utf-8").read():
    sys.exit("Уже установлено.")

differ = []
for rel, h in ORIG.items():
    if h is None:
        if os.path.exists(p(rel)):
            differ.append(f"{rel} — уже есть такой файл")
        continue
    if not os.path.exists(p(rel)):
        differ.append(f"{rel} — нет файла")
        continue
    got = hashlib.sha256(open(p(rel), "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    if got != h:
        differ.append(rel)
if differ:
    print("  ! отличаются от версии на GitHub: " + ", ".join(differ))
    sys.exit("Эти файлы у тебя изменены — ничего не тронул. Сделай git pull (или пришли мне вывод), потом запусти снова.")

backup = p(time.strftime(TAG + "%Y%m%d_%H%M%S"))
for rel, h in ORIG.items():
    if h is not None:
        os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
        shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, data in NEW.items():
    os.makedirs(os.path.dirname(p(rel)) or ROOT, exist_ok=True)
    with open(p(rel), "wb") as f:
        f.write(base64.b64decode(data))
print("  ✓ утренняя сводка: каждое утро уведомлением, время — в настройках телефона")
print("  ✓ разговор без кнопки: Atlas слушает после каждого ответа, пока не скажешь «всё»")

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
suites = [f for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
for suite in suites:
    try:
        r = subprocess.run([sys.executable, p("tests/" + suite)], cwd=ROOT, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=300, env=env)
        out, code = r.stdout + r.stderr, r.returncode
    except subprocess.TimeoutExpired:
        out, code = "✗ тесты не закончились за 5 минут", 1
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", out)
    good = code == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} tests/{suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        lines = out.splitlines()
        for i, ln in enumerate(lines):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in lines[i:i + 7]))
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено.")
print("\nГотово. Дальше: git add -A, git commit, git push — Render обновится сам за 3–5 минут.")
print("На телефоне: закрой и открой Atlas → шестерёнка → «Разговор без кнопки» и «Утренняя сводка» → «Прислать сейчас».")

